class Solution {
public:
    int superEggDrop(int k, int n) {
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (check(mid, k, n) >= n) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }

private:
    long long check(int m, int k, int n) {
        long long sum = 0;
        long long c = 1;
        for (int i = 1; i <= k; ++i) {
            c = c * (m - i + 1) / i;
            if (c > n) c = n;
            sum += c;
            if (sum >= n) return sum;
        }
        return sum;
    }
};
